package com.felipebz.flr.api

/**
 * The AstVisitor allows to visit some desired AstNode. The AstAndTokenVisitor extends this first interface to add a new feature : being
 * visited for each Token generated by the Lexer.
 *
 */
public interface AstAndTokenVisitor : AstVisitor {
    /**
     * Called sequentially for each token generated by the Lexer
     *
     * @param token
     * Token to visit
     */
    public fun visitToken(token: Token?)
}
